const fs=require("fs");const css=fs.readFileSync("/tmp/fonts.css","utf8");
const blocks=css.split("@font-face").slice(1).map(b=>"@font-face"+b.split("}")[0]+"}");
const out=[];
for(const b of blocks){ if(!b.includes("U+0000-00FF")) continue; const fam=(b.match(/font-family: \x27([^\x27]+)/)||[])[1]; const wt=(b.match(/font-weight: (\d+)/)||[])[1]; const style=(b.match(/font-style: (\w+)/)||[])[1]; const url=(b.match(/url\((https:[^)]+)\)/)||[])[1]; if(!fam||!url) continue; const file=fam.replace(/\s/g,"")+"-"+wt+(style==="italic"?"i":"")+".woff2"; out.push({fam,wt,style,url,file}); }
console.log(out.map(o=>o.fam+" "+o.wt+" "+o.style+" "+o.file).join("\n"));
fs.writeFileSync("/tmp/fontlist.json",JSON.stringify(out));
'

