@font-face{font-family:'Cinzel';src:url('/fonts/Cinzel-400.woff2') format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:'Cinzel';src:url('/fonts/Cinzel-700.woff2') format('woff2');font-weight:700;font-display:swap}
@font-face{font-family:'Cinzel';src:url('/fonts/Cinzel-900.woff2') format('woff2');font-weight:900;font-display:swap}
@font-face{font-family:'Alegreya Sans';src:url('/fonts/AlegreyaSans-400.woff2') format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:'Alegreya Sans';src:url('/fonts/AlegreyaSans-500.woff2') format('woff2');font-weight:500;font-display:swap}
