  .game-sub{letter-spacing:.4em;font-size:11px}
  .menu-btn span{font-size:17px}
  .creator-foot{flex-wrap:wrap}
  .creator-hint{order:3;width:100%;flex:auto}
  .classes{grid-template-columns:1fr 1fr}
  .field{grid-template-columns:60px 1fr}
  .panel{max-height:94vh}
  .panel-foot span{display:none}
  .panel-foot{justify-content:flex-end}
  .dialogue-box{padding:14px;gap:12px}
  .dlg-portrait{flex-basis:54px}.dlg-portrait .cat-avatar{width:54px;height:54px}
  .dlg-text{font-size:13px;min-height:36px}
  .toasts{top:calc(80px + var(--safe-t));max-width:200px}
  .end-panel{padding:26px}
