import { QUESTS, QUESTS_BY_ID, LANDMARKS } from '../core/data.js';
import { dist2d } from '../core/noise.js';

const MAIN_ORDER = ['main1', 'main2', 'main3', 'main4', 'main5'];

export class QuestLog {
  constructor(game) {
    this.game = game;
    this.states = new Map();
    this.tracked = null;
    this.reachTimer = 0;
  }

  isActive(id) { const s = this.states.get(id); return !!s && !s.complete; }
  isComplete(id) { return !!this.states.get(id)?.complete; }
  get(id) { return this.states.get(id); }
  def(id) { return QUESTS_BY_ID[id]; }

  canStart(id) {
    const q = QUESTS_BY_ID[id];
    if (!q || this.isActive(id) || this.isComplete(id)) return false;
    if (q.type === 'main') {
      const i = MAIN_ORDER.indexOf(id);
      if (i > 0 && !this.isComplete(MAIN_ORDER[i - 1])) return false;
    }
    return true;
  }

  start(id, silent = false) {
    if (!this.canStart(id)) return false;
    const q = QUESTS_BY_ID[id];
    this.states.set(id, { id, stage: 0, progress: 0, complete: false, started: true });
    if (!this.tracked || q.type === 'main') this.tracked = id;
    if (!silent) {
      this.game.ui.toast(`<b>Quest started:</b> ${q.title}`, 'quest');
      this.game.audio.playQuest();
      this.game.ui.showArea(q.title, q.type === 'main' ? 'Main quest' : 'Side quest');
    }
    this.game.ui.refreshQuests();
    this.game.ui.updateHUD();
    return true;
  }

  currentStage(state) {
    const q = QUESTS_BY_ID[state.id];
    return q?.stages[state.stage];
  }

  event(type, target, amount = 1) {
    let changed = false;
    for (const state of this.states.values()) {
      if (state.complete) continue;
      const stage = this.currentStage(state);
      if (!stage || stage.event !== type || stage.target !== target) continue;
      if (type === 'kill' || type === 'collect') {
        state.progress = Math.min(stage.count || 1, state.progress + amount);
        if (state.progress < (stage.count || 1)) {
          this.game.ui.updateHUD();
          this.game.ui.refreshQuests();
          continue;
        }
      }
      this.advance(state);
      changed = true;
    }
    if (changed) {
      this.game.ui.updateHUD();
      this.game.ui.refreshQuests();
      this.game.save(true);
    }
  }

  advance(state) {
    const q = QUESTS_BY_ID[state.id];
    state.stage++;
    state.progress = 0;
    if (state.stage >= q.stages.length) {
      this.complete(state);
    } else {
      this.game.ui.toast(`<b>${q.title}</b><br>${q.stages[state.stage].text}`, 'quest');
      this.game.audio.playQuest();
    }
  }

  complete(state) {
    const q = QUESTS_BY_ID[state.id];
    state.complete = true;
    state.stage = q.stages.length - 1;
    const r = q.reward || {};
    if (r.xp) this.game.player.addXP(r.xp);
    if (r.gold) this.game.inventory.add('gold', r.gold);
    for (const item of (r.items || [])) this.game.inventory.add(item, 1, true);
    this.game.ui.toast(`<b>Quest complete:</b> ${q.title}<br>+${r.xp || 0} XP · +${r.gold || 0} gold`, 'good');
    this.game.audio.playQuestComplete();
    if (this.tracked === state.id) {
      const next = [...this.states.values()].find(s => !s.complete && QUESTS_BY_ID[s.id].type === 'main');
      this.tracked = next ? next.id : [...this.states.values()].find(s => !s.complete)?.id || null;
    }
    if (state.id === 'main5') this.game.victory();
    this.game.ui.refreshQuests();
  }

  pendingTalk(npcId) {
    for (const state of this.states.values()) {
      if (state.complete) continue;
      const stage = this.currentStage(state);
      if (stage && stage.event === 'talk' && stage.target === npcId) return state;
    }
    return null;
  }

  offersFor(npcId) {
    return QUESTS.filter(q => q.giver === npcId && this.canStart(q.id));
  }

  turnIn(npcId) {
    const state = this.pendingTalk(npcId);
    if (!state) return false;
    this.event('talk', npcId, 1);
    return true;
  }

  update(dt) {
    this.reachTimer -= dt;
    if (this.reachTimer > 0) return;
    this.reachTimer = 0.45;
    const p = this.game.player.position;
    for (const state of this.states.values()) {
      if (state.complete) continue;
      const stage = this.currentStage(state);
      if (!stage || stage.event !== 'reach') continue;
      const l = LANDMARKS[stage.target];
      if (!l) continue;
      if (dist2d(p.x, p.z, l.x, l.z) < (l.radius || 30) * 0.82) this.event('reach', stage.target, 1);
    }
  }

  markerPosition(id) {
    const state = this.states.get(id);
    if (!state || state.complete) return null;
    const stage = this.currentStage(state);
    if (!stage) return null;
    const marker = stage.marker || stage.target;
    const npc = this.game.npcs?.byId?.[marker];
    if (npc) {
      if (npc.mapPos) return { x: npc.mapPos.x, z: npc.mapPos.z, name: npc.name };
      return { x: npc.group.position.x, z: npc.group.position.z, name: npc.name };
    }
    const l = LANDMARKS[marker];
    if (l) return { x: l.x, z: l.z, name: l.name };
    return null;
  }

  trackedInfo() {
    if (!this.tracked) {
      const main = [...this.states.values()].find(s => !s.complete && QUESTS_BY_ID[s.id].type === 'main');
      if (main) this.tracked = main.id;
    }
    const state = this.tracked ? this.states.get(this.tracked) : null;
    if (!state || state.complete) return null;
    const q = QUESTS_BY_ID[state.id];
    const stage = this.currentStage(state);
    if (!stage) return null;
    let text = stage.text;
    if ((stage.count || 1) > 1) text = text.replace(/\(\d+\/\d+\)/, `(${state.progress}/${stage.count})`);
    return { id: state.id, title: q.title, type: q.type, text, stage, marker: this.markerPosition(state.id), progress: state.progress, count: stage.count || 1 };
  }

  save() {
    return { states: [...this.states.entries()], tracked: this.tracked };
  }
  load(data) {
    if (!data) return;
    this.states = new Map(data.states || []);
    this.tracked = data.tracked || null;
  }
}

import * as THREE from 'three';
import { makeGlowTexture } from '../world/buildings.js';

const tmpV = new THREE.Vector3();

export class Effects {
  constructor(game) {
    this.game = game;
    this.scene = game.scene;
    this.projectiles = [];
    this.particles = [];
    this.arcs = [];
    this.lines = [];
    this.rings = [];
    this.lightPool = [];
    this.glowTex = makeGlowTexture();
  }

  burst(pos, color = 0xffcf8a, count = 14, speed = 3, life = 0.8, size = 0.12) {
    const geo = new THREE.SphereGeometry(size, 4, 3);
    for (let i = 0; i < count; i++) {
      const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
      const m = new THREE.Mesh(geo, mat);
      m.position.copy(pos);
      const dir = new THREE.Vector3(Math.random() - 0.5, Math.random() * 0.8 + 0.1, Math.random() - 0.5).normalize();
      m.userData.vel = dir.multiplyScalar(speed * (0.4 + Math.random()));
      m.userData.life = life * (0.6 + Math.random() * 0.6);
      m.userData.max = m.userData.life;
      this.scene.add(m);
      this.particles.push(m);
    }
  }

  spark(pos, color = 0xffe0a0) { this.burst(pos, color, 7, 2.2, 0.35, 0.08); }

  slash(pos, yaw, color = 0xfff0cf) {
    const geo = new THREE.RingGeometry(0.9, 2.1, 18, 1, -0.7, 1.4);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.75, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.rotation.z = -yaw + Math.PI / 2;
    mesh.position.copy(pos).add(new THREE.Vector3(0, 1.1, 0));
    this.scene.add(mesh);
    this.arcs.push({ mesh, life: 0.22, max: 0.22 });
  }

  ring(pos, color = 0xffd27a, radius = 4, life = 0.5) {
    const geo = new THREE.RingGeometry(radius * 0.2, radius, 32);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.7, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.copy(pos).add(new THREE.Vector3(0, 0.15, 0));
    this.scene.add(mesh);
    this.rings.push({ mesh, life, max: life, radius });
  }

  beam(from, to, color = 0x9fd8ff, life = 0.25) {
    const points = [];
    const steps = 8;
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const p = from.clone().lerp(to, t);
      if (i > 0 && i < steps) {
        p.x += (Math.random() - 0.5) * 0.8;
        p.y += (Math.random() - 0.5) * 0.8;
        p.z += (Math.random() - 0.5) * 0.8;
      }
      points.push(p);
    }
    const geo = new THREE.BufferGeometry().setFromPoints(points);
    const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending });
    const line = new THREE.Line(geo, mat);
    this.scene.add(line);
    this.lines.push({ mesh: line, life, max: life });
    const light = new THREE.PointLight(color, 16, 25, 2);
    light.position.copy(to);
    this.scene.add(light);
    this.lightPool.push({ light, life: 0.25 });
    this.burst(to, color, 16, 4, 0.5, 0.1);
  }

  spawnProjectile(o) {
    const group = new THREE.Group();
    const color = o.color || 0xff9b45;
    const core = new THREE.Mesh(new THREE.SphereGeometry(o.size || 0.22, 8, 6), new THREE.MeshBasicMaterial({ color }));
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color, transparent: true, opacity: 0.75, depthWrite: false, blending: THREE.AdditiveBlending }));
    glow.scale.setScalar((o.size || 0.22) * 9);
    group.add(core, glow);
    group.position.copy(o.pos);
    this.scene.add(group);
    const light = new THREE.PointLight(color, 7, 12, 2);
    group.add(light);
    const p = {
      group, core, color, light, vel: o.dir.clone().normalize().multiplyScalar(o.speed || 26),
      damage: o.damage || 10, owner: o.owner || 'player', type: o.type || 'fire',
      radius: o.radius || 0.55, life: o.life || 3.2, age: 0, onHit: o.onHit,
      aoe: o.aoe || 0, slow: o.slow || 0, target: o.target || null, homing: o.homing || 0,
    };
    this.projectiles.push(p);
    return p;
  }

  update(dt) {
    const game = this.game;
    // particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.userData.life -= dt;
      if (p.userData.life <= 0) { this.scene.remove(p); p.material.dispose(); this.particles.splice(i, 1); continue; }
      p.userData.vel.y -= 9.8 * dt;
      p.position.addScaledVector(p.userData.vel, dt);
      p.material.opacity = p.userData.life / p.userData.max;
      p.scale.setScalar(0.5 + p.userData.life / p.userData.max);
    }
    // arcs
    for (let i = this.arcs.length - 1; i >= 0; i--) {
      const a = this.arcs[i];
      a.life -= dt;
      if (a.life <= 0) { this.scene.remove(a.mesh); a.mesh.geometry.dispose(); a.mesh.material.dispose(); this.arcs.splice(i, 1); continue; }
      a.mesh.material.opacity = 0.75 * (a.life / a.max);
      a.mesh.scale.setScalar(1 + (1 - a.life / a.max) * 0.35);
    }
    // rings
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      if (r.life <= 0) { this.scene.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose(); this.rings.splice(i, 1); continue; }
      const t = 1 - r.life / r.max;
      r.mesh.scale.setScalar(0.4 + t * 1.5);
      r.mesh.material.opacity = 0.7 * (1 - t);
    }
    // lines
    for (let i = this.lines.length - 1; i >= 0; i--) {
      const l = this.lines[i];
      l.life -= dt;
      if (l.life <= 0) { this.scene.remove(l.mesh); l.mesh.geometry.dispose(); l.mesh.material.dispose(); this.lines.splice(i, 1); continue; }
      l.mesh.material.opacity = l.life / l.max;
    }
    for (let i = this.lightPool.length - 1; i >= 0; i--) {
      const l = this.lightPool[i];
      l.life -= dt;
      l.light.intensity = Math.max(0, 16 * (l.life / 0.25));
      if (l.life <= 0) { this.scene.remove(l.light); this.lightPool.splice(i, 1); }
    }
    // projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.age += dt;
      p.life -= dt;
      let remove = false;
      if (p.homing && p.target && p.target.alive) {
        const desired = p.target.group.position.clone().add(new THREE.Vector3(0, 1, 0)).sub(p.group.position).normalize().multiplyScalar(p.vel.length());
        p.vel.lerp(desired, Math.min(1, dt * 3));
      }
      p.group.position.addScaledVector(p.vel, dt);
      p.group.position.y += Math.sin(p.age * 12) * 0.002;
      const ground = game.world.groundHeight(p.group.position.x, p.group.position.z);
      if (p.group.position.y < ground + 0.2) remove = true;
      if (p.age > p.life) remove = true;
      if (!remove) {
        if (p.owner === 'player') {
          for (const e of game.enemies) {
            if (!e.alive || e.interior !== game.world.activeInterior?.name) continue;
            tmpV.copy(e.group.position).add(new THREE.Vector3(0, e.hitHeight || 1, 0));
            if (p.group.position.distanceTo(tmpV) < (e.hitRadius || 0.7) + p.radius) {
              this.projectileHit(p, e);
              remove = true; break;
            }
          }
        } else {
          const targets = [game.player, ...game.companions];
          for (const t of targets) {
            if (!t || t.dead) continue;
            tmpV.copy(t.position).add(new THREE.Vector3(0, 1, 0));
            if (p.group.position.distanceTo(tmpV) < 1.0 + p.radius) {
              this.projectileHit(p, t);
              remove = true; break;
            }
          }
        }
      }
      if (remove) this.explodeProjectile(p, i);
    }
  }

  projectileHit(p, target) {
    if (p.onHit) p.onHit(target, p);
    else if (target.takeDamage) target.takeDamage(p.damage, p);
  }

  explodeProjectile(p, index) {
    const game = this.game;
    const pos = p.group.position.clone();
    this.scene.remove(p.group);
    p.core.geometry.dispose(); p.core.material.dispose();
    if (p.aoe > 0) {
      this.burst(pos, p.color, 24, 6, 0.7, 0.14);
      this.ring(pos, p.color, p.aoe, 0.5);
      const targets = p.owner === 'player' ? game.enemies : [game.player, ...game.companions];
      for (const t of targets) {
        if (!t || !t.alive || t.dead) continue;
        const d = t.group ? t.group.position.distanceTo(pos) : t.position.distanceTo(pos);
        if (d < p.aoe) {
          const falloff = 1 - (d / p.aoe) * 0.55;
          if (t.takeDamage) t.takeDamage(Math.round(p.damage * falloff), p);
        }
      }
      this.game.audio.playExplosion();
      this.game.player.cameraShake = Math.max(this.game.player.cameraShake, 0.22);
    } else {
      this.burst(pos, p.color, 10, 3, 0.45, 0.1);
    }
    this.projectiles.splice(index, 1);
  }

  damageNumber(pos, amount, kind = '') {
    const game = this.game;
    const v = pos.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.6, 1.4 + Math.random() * 0.4, 0));
    v.project(game.camera);
    const x = (v.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight;
    const el = document.createElement('div');
    el.className = 'dmg ' + kind;
    el.textContent = (kind === 'heal' ? '+' : '') + amount;
    el.style.left = x + 'px'; el.style.top = y + 'px';
    game.ui.floatLayer.appendChild(el);
    setTimeout(() => el.remove(), 1000);
  }

  screenFlash(color = '#ffcf8a', alpha = 0.22) {
    const el = document.createElement('div');
    el.style.cssText = `position:fixed;inset:0;background:${color};opacity:${alpha};pointer-events:none;z-index:15;transition:opacity .35s`;
    document.body.appendChild(el);
    requestAnimationFrame(() => { el.style.opacity = '0'; });
    setTimeout(() => el.remove(), 500);
  }
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, metalness: 0 });
const eyeMat = new THREE.MeshBasicMaterial({ vertexColors: true });

function paint(geo, hex) {
  const c = new THREE.Color(hex);
  const n = geo.attributes.position.count;
  const arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}
function add(list, geo, hex, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
  geo.scale(scale[0], scale[1], scale[2]);
  if (rot[0] || rot[1] || rot[2]) geo.rotateX(rot[0]), geo.rotateY(rot[1]), geo.rotateZ(rot[2]);
  geo.translate(pos[0], pos[1], pos[2]);
  paint(geo, hex); list.push(geo);
}

const KINDS = {
  wolf: { body: '#9aa4ab', belly: '#d8dde0', dark: '#4f5a61', eye: '#ffcf6b', scale: 1.0, len: 1.5, height: 1.05, ears: 'point', tail: 0.8, snout: 0.5 },
  frostRat: { body: '#8a7c6a', belly: '#c9bca8', dark: '#4e4337', eye: '#ff8a5c', scale: 1.0, len: 0.8, height: 0.55, ears: 'round', tail: 0.9, snout: 0.5 },
  bear: { body: '#d4d9dc', belly: '#eef2f4', dark: '#7b858b', eye: '#ffb35c', scale: 1.0, len: 2.2, height: 1.5, ears: 'round', tail: 0.35, snout: 0.6 },
  deer: { body: '#9b7f61', belly: '#d8c9b4', dark: '#5c4631', eye: '#2a2018', scale: 1.0, len: 1.4, height: 1.2, ears: 'leaf', tail: 0.25, snout: 0.55 },
  rabbit: { body: '#d9d2c6', belly: '#f2ede4', dark: '#9c9184', eye: '#3a2b22', scale: 1.0, len: 0.5, height: 0.45, ears: 'long', tail: 0.3, snout: 0.3 },
};

export function createBeast(kind = 'wolf', colorOverride = null) {
  const def = KINDS[kind] || KINDS.wolf;
  const bodyColor = colorOverride || def.body;
  const root = new THREE.Group();
  const rig = new THREE.Group();
  root.add(rig);
  const bodyLen = def.len, bodyH = def.height;
  const parts = [];
  // body
  add(parts, new THREE.SphereGeometry(0.36, 9, 7), bodyColor, [0, bodyH, 0], [0, 0, 0], [1.0, 0.9, bodyLen * 1.4]);
  add(parts, new THREE.SphereGeometry(0.3, 8, 6), def.belly, [0, bodyH - 0.12, 0.05], [0, 0, 0], [0.9, 0.7, bodyLen * 1.25]);
  // neck + head
  const head = new THREE.Group();
  head.position.set(0, bodyH + 0.28, bodyLen * 0.72);
  rig.add(head);
  const headParts = [];
  add(headParts, new THREE.SphereGeometry(0.3, 9, 7), bodyColor, [0, 0, 0], [0, 0, 0], [1, 0.92, 1.05]);
  add(headParts, new THREE.SphereGeometry(0.18, 7, 5), def.belly, [0, -0.08, 0.27], [0, 0, 0], [1.1, 0.7, 1.0]);
  add(headParts, new THREE.SphereGeometry(0.06, 5, 4), '#20171a', [0, -0.06, 0.43], [0, 0, 0], [1, 0.8, 0.8]);
  if (def.ears === 'point') {
    add(headParts, new THREE.ConeGeometry(0.1, 0.24, 4), def.dark, [-0.18, 0.26, -0.02], [0, 0, 0.2]);
    add(headParts, new THREE.ConeGeometry(0.1, 0.24, 4), def.dark, [0.18, 0.26, -0.02], [0, 0, -0.2]);
  } else if (def.ears === 'round') {
    add(headParts, new THREE.SphereGeometry(0.12, 6, 5), def.dark, [-0.2, 0.22, -0.04], [0, 0, 0], [1, 1, 0.4]);
    add(headParts, new THREE.SphereGeometry(0.12, 6, 5), def.dark, [0.2, 0.22, -0.04], [0, 0, 0], [1, 1, 0.4]);
  } else if (def.ears === 'long') {
    add(headParts, new THREE.CapsuleGeometry(0.06, 0.3, 3, 5), def.dark, [-0.12, 0.32, -0.02], [0.1, 0, 0.1]);
    add(headParts, new THREE.CapsuleGeometry(0.06, 0.3, 3, 5), def.dark, [0.12, 0.32, -0.02], [0.1, 0, -0.1]);
  } else {
    add(headParts, new THREE.ConeGeometry(0.13, 0.22, 4), def.dark, [-0.22, 0.18, 0], [0, 0, 0.8]);
    add(headParts, new THREE.ConeGeometry(0.13, 0.22, 4), def.dark, [0.22, 0.18, 0], [0, 0, -0.8]);
  }
  const headMesh = new THREE.Mesh(mergeGeometries(headParts, false), mat);
  headMesh.castShadow = true;
  head.add(headMesh);
  // eyes
  const eyeParts = [];
  add(eyeParts, new THREE.SphereGeometry(0.06, 6, 5), def.eye, [-0.14, 0.05, 0.24], [0, 0, 0], [1, 1, 0.5]);
  add(eyeParts, new THREE.SphereGeometry(0.06, 6, 5), def.eye, [0.14, 0.05, 0.24], [0, 0, 0], [1, 1, 0.5]);
  add(eyeParts, new THREE.SphereGeometry(0.028, 5, 4), '#090909', [-0.14, 0.05, 0.285], [0, 0, 0], [0.6, 1, 0.4]);
  add(eyeParts, new THREE.SphereGeometry(0.028, 5, 4), '#090909', [0.14, 0.05, 0.285], [0, 0, 0], [0.6, 1, 0.4]);
  head.add(new THREE.Mesh(mergeGeometries(eyeParts, false), eyeMat));

  const bodyMesh = new THREE.Mesh(mergeGeometries(parts, false), mat);
  bodyMesh.castShadow = true;
  rig.add(bodyMesh);

  // legs
  const legs = [];
  const legPositions = [
    [-0.28, bodyH - 0.18, bodyLen * 0.45], [0.28, bodyH - 0.18, bodyLen * 0.45],
    [-0.28, bodyH - 0.18, -bodyLen * 0.45], [0.28, bodyH - 0.18, -bodyLen * 0.45],
  ];
  for (const [x, y, z] of legPositions) {
    const pivot = new THREE.Group();
    pivot.position.set(x, y, z);
    const lp = [];
    add(lp, new THREE.CapsuleGeometry(0.09, 0.32, 3, 5), bodyColor, [0, -0.22, 0], [0, 0, 0], [1, 1, 1]);
    add(lp, new THREE.SphereGeometry(0.1, 6, 5), def.dark, [0, -0.45, 0.03], [0, 0, 0], [1, 0.5, 1.4]);
    const lm = new THREE.Mesh(mergeGeometries(lp, false), mat);
    lm.castShadow = true;
    pivot.add(lm);
    rig.add(pivot);
    legs.push(pivot);
  }
  // tail
  const tail = new THREE.Group();
  tail.position.set(0, bodyH + 0.02, -bodyLen * 0.68);
  const tp = [];
  add(tp, new THREE.CapsuleGeometry(0.07, def.tail * 0.9, 3, 5), def.dark, [0, -0.05, -def.tail * 0.4], [Math.PI * 0.42, 0, 0]);
  add(tp, new THREE.SphereGeometry(0.08, 5, 4), def.belly, [0, -0.1, -def.tail * 0.78]);
  const tm = new THREE.Mesh(mergeGeometries(tp, false), mat);
  tail.add(tm);
  rig.add(tail);

  const anim = { t: Math.random() * 10, phase: Math.random() * 10, dead: 0, attack: 0, hurt: 0 };
  root.scale.setScalar(def.scale);

  const beast = {
    root, rig, head, bodyMesh, legs, tail, anim, kind,
    playAttack() { anim.attack = 0.36; },
    playHurt() { anim.hurt = 0.25; },
    die() { anim.dead = 1; },
    update(dt, s = {}) {
      anim.t += dt;
      anim.attack = Math.max(0, anim.attack - dt);
      anim.hurt = Math.max(0, anim.hurt - dt);
      const speed = s.speed || 0;
      const moving = speed > 0.1;
      if (moving) anim.phase += dt * (6 + speed * 1.6);
      const sw = Math.sin(anim.phase);
      const gait = Math.min(1.2, speed / 3);
      legs[0].rotation.x = sw * 0.65 * gait;
      legs[1].rotation.x = -sw * 0.65 * gait;
      legs[2].rotation.x = -sw * 0.65 * gait;
      legs[3].rotation.x = sw * 0.65 * gait;
      rig.position.y = moving ? Math.abs(sw) * 0.04 * gait : Math.sin(anim.t * 1.8) * 0.01;
      head.rotation.x = Math.sin(anim.t * 1.2) * 0.04 - anim.attack * 0.3;
      head.rotation.y = s.lookYaw || 0;
      tail.rotation.y = Math.sin(anim.t * (moving ? 5 : 1.5)) * 0.3;
      tail.rotation.x = -0.2 + Math.sin(anim.t * 1.1) * 0.1;
      if (anim.dead) {
        rig.rotation.z += (1.5 - rig.rotation.z) * Math.min(1, dt * 4);
        rig.position.y += (-0.15 - rig.position.y) * Math.min(1, dt * 4);
      }
    },
  };
  root.userData.beast = beast;
  return beast;
}

