152: const INTERIOR_NPCS = NPC_DEFS.filter(d => d.interior);
153: const OUTDOOR_DEFS = NPC_DEFS.filter(d => !d.interior);
154: 
155: export class NPCManager {
156:   constructor(game) {
157:     this.game = game;
158:     this.rng = makeRng(5521);
159:     this.list = [];
160:     this.byId = {};
161:     this.interiorId = null;
162:     this.barks = 0;
163:     this.ambientTimer = 8;
164:     this.createOutdoor();
165:     this.createAmbient();
166:   }
167: 
168:   buildNpc(def, group, local = false) {
169:     const cat = createCat({
170:       breed: def.breed, fur: def.fur, eye: def.eye, scale: def.scale || 1,
171:       weapon: def.gear?.weapon, armor: def.gear?.armor, bow: def.gear?.bow, scarf: def.gear?.scarf,
172:     });
173:     cat.root.name = 'npc-' + def.id;
174:     group.add(cat.root);
175:     const npc = {
176:       ...def, def, cat, group: cat.root, local, companion: false, recruited: false,
177:       hp: 100, maxHp: 100, alive: true, dead: false, speed: 0,
178:       target: null, state: 'idle', idleT: this.rng.range(0, 4), chatT: this.rng.range(8, 30),
179:       wanderT: 0, stuck: 0, attackCd: 0, downed: 0, marker: null, facing: 0,
180:       interior: def.interior || null, baseX: def.x, baseZ: def.z,
181:       mapPos: def.mapPos || { x: def.x, z: def.z },
182:     };
183:     if (!local) {
184:       npc.group.position.set(def.x, this.game.world.terrain.heightAt(def.x, def.z), def.z);
185:     } else {
186:       npc.group.position.set(def.x, 0, def.z);
187:     }
188:     // quest marker
189:     const marker = new THREE.Mesh(new THREE.OctahedronGeometry(0.16, 0), new THREE.MeshBasicMaterial({ color: 0xffcf6a }));
190:     marker.position.y = 2.45;
191:     marker.visible = false;
192:     npc.group.add(marker);
193:     npc.marker = marker;
194:     this.list.push(npc);
195:     this.byId[npc.id] = npc;
196:     return npc;
197:   }
198: 
199:   createOutdoor() {
200:     for (const def of OUTDOOR_DEFS) this.buildNpc(def, this.game.world.group);
201:   }
202: 
203:   createAmbient() {
204:     const spots = [
205:       { x: -292, z: -128, n: 5, r: 20 }, { x: -260, z: -180, n: 3, r: 18 },
206:       { x: 190, z: 316, n: 3, r: 14 }, { x: -392, z: 130, n: 2, r: 16 },
207:       { x: 352, z: 214, n: 2, r: 12 }, { x: 238, z: -280, n: 2, r: 12 },
208:     ];
209:     let idx = 0;
210:     for (const s of spots) {
211:       for (let i = 0; i < s.n; i++) {
212:         const look = randomCatLook(this.rng, {});
213:         const id = 'citizen' + (idx++);
214:         const x = s.x + this.rng.range(-s.r, s.r);
215:         const z = s.z + this.rng.range(-s.r, s.r);
216:         const def = {
217:           id, name: AMBIENT_NAMES[idx % AMBIENT_NAMES.length], role: 'Citizen',
218:           breed: look.breed, fur: look.fur, eye: look.eye, scale: this.rng.range(0.86, 1.06),
219:           x, z, home: { x: s.x, z: s.z }, work: { x: s.x + this.rng.range(-6, 6), z: s.z + this.rng.range(-6, 6) },
220:           mapPos: { x, z }, ambient: true,
221:           greet: [this.rng.pick(AMBIENT_LINES), this.rng.pick(AMBIENT_LINES)],
222:           lore: this.rng.pick(['I have lived here all my lives.', 'The snow is louder than it looks.', 'Do not trust the geese.']),
223:           gear: this.rng.chance(0.25) ? { armor: 'leatherArmor' } : {},
224:         };
225:         const npc = this.buildNpc(def, this.game.world.group);
226:         npc.home = def.home; npc.work = def.work;
227:         npc.wander = { x: s.x, z: s.z, r: s.r };
228:       }
229:     }
230:   }
231: 
232:   setInterior(id) {
233:     this.interiorId = id;
234:     if (id) {
235:       const interior = this.game.world.interiors.get(id);
236:       if (!interior) return;
237:       // hide outdoor npcs
238:       for (const npc of this.list) if (!npc.interior) npc.group.visible = false;
239:       // create interior npcs on demand
240:       for (const def of INTERIOR_NPCS.filter(d => d.interior === id)) {
241:         if (!this.byId[def.id]) {
242:           const npc = this.buildNpc(def, interior.group, true);
243:           npc.interior = id;
244:           npc.home = { x: def.x, z: def.z }; npc.work = { x: def.x, z: def.z };
245:         }
246:         this.byId[def.id].group.visible = true;
247:       }
248:       for (const npc of this.list) if (npc.interior && npc.interior !== id) npc.group.visible = false;
249:     } else {
250:       for (const npc of this.list) {
251:         if (!npc.interior) npc.group.visible = true;
252:         else if (npc.companion) {
253:           // companions return to the player
254:           this.game.world.group.add(npc.group);
255:           const p = this.game.player.position;
256:           npc.group.position.set(p.x + 1.6, this.game.world.terrain.heightAt(p.x + 1.6, p.z + 1.6), p.z + 1.6);
257:           npc.group.visible = true;
258:         } else npc.group.visible = false;
259:       }
260:     }
261:   }
262: 
263:   talkables() {
264:     return this.list.filter(n => n.group.visible && !n.dead && (!this.interiorId ? !n.interior : n.interior === this.interiorId));
265:   }
266: 
267:   nearestTalkable(pos, maxDist = 3.4) {
268:     let best = null, bd = maxDist;
269:     for (const n of this.talkables()) {
270:       if (n.companion) continue;
271:       const d = pos.distanceTo(n.group.position);
272:       if (d < bd) { bd = d; best = n; }
273:     }
274:     return best;
275:   }
276: 
277:   recruit(npc) {
278:     if (npc.companion) return;
279:     npc.companion = true; npc.recruited = true; npc.hp = 140; npc.maxHp = 140;
280:     this.game.companions.push(npc);
281:     this.game.quests.event('recruit', npc.id, 1);
282:     this.game.ui.toast(`<b>${npc.name}</b> joins you.`, 'good');
283:     this.game.audio.playQuestComplete();
284:   }
285: 
286:   setCompanionWait(npc, wait) {
287:     npc.waiting = wait;
288:     this.game.ui.toast(wait ? `${npc.name} will wait here.` : `${npc.name} follows.`);
289:   }
290: 
291:   update(dt) {
292:     const game = this.game;
293:     const hour = game.time.hours;
294:     const night = hour >= 21 || hour < 7;
295:     const playerPos = game.player.position;
296:     let nearestEnemy = null, ned = 18;
297:     for (const e of game.enemies) {
298:       if (!e.alive) continue;
299:       const d = playerPos.distanceTo(e.group.position);
300:       if (d < ned) { ned = d; nearestEnemy = e; }
301:     }
302:     for (const npc of this.list) {
303:       if (!npc.group.visible) continue;
304:       if (npc.dead) continue;
305:       if (npc.companion) this.updateCompanion(npc, dt, nearestEnemy);
306:       else if (npc.guard && nearestEnemy && !this.interiorId && ned < 15) this.updateGuard(npc, dt, nearestEnemy);
307:       else if (npc.ambient) this.updateAmbient(npc, dt, night, hour);
308:       else this.updateScheduled(npc, dt, night, hour);
309:       // face player while talking
310:       if (game.mode === 'dialogue' && game.dialogue?.npc === npc) {
311:         const d = playerPos.clone().sub(npc.group.position);
312:         npc.facing = Math.atan2(d.x, d.z);
313:       }
314:       npc.group.rotation.y += angleDelta(npc.group.rotation.y, npc.facing) * Math.min(1, dt * 6);
315:       npc.cat.update(dt, { speed: npc.speed, sitting: npc.sitting, sleeping: npc.sleeping, talking: game.mode === 'dialogue' && game.dialogue?.npc === npc, lookYaw: npc.lookYaw || 0 });
316:       // marker
317:       const pending = game.quests.pendingTalk(npc.id);
318:       const offers = game.quests.offersFor(npc.id);
319:       const show = !!(pending || offers.length);
320:       npc.marker.visible = show && !npc.companion;
321:       if (show) {
322:         npc.marker.position.y = 2.45 + Math.sin(performance.now() * 0.002 + npc.group.position.x) * 0.08;
323:         npc.marker.rotation.y += dt * 1.5;
324:         npc.marker.material.color.set(pending ? 0x8ee39b : 0xffcf6a);
325:       }
326:       // ambient barks
327:       npc.chatT -= dt;
328:       if (npc.chatT <= 0) {
329:         npc.chatT = this.rng.range(18, 44);
330:         if (playerPos.distanceTo(npc.group.position) < 13 && game.mode === 'play' && !npc.companion) {
331:           const line = this.rng.pick(npc.ambient ? AMBIENT_LINES : (npc.greet || AMBIENT_LINES));
332:           game.ui.subtitle(`${npc.name}: ${line}`, 4.5);
333:           game.audio.meow(this.rng.range(0.7, 1.2));
334:           if (npc.ambient) npc.cat.playTalk();
335:         }
336:       }
337:     }
338:     // ambient meows near player even without dialogue
339:     this.ambientTimer -= dt;
340:     if (this.ambientTimer <= 0) {
341:       this.ambientTimer = this.rng.range(16, 35);
342:       if (game.mode === 'play') {
343:         game.audio.meow(this.rng.range(0.6, 1.4));
344:         if (Math.random() < 0.45) game.ui.subtitle(this.rng.pick(['Somewhere, a cat is very disappointed in you.', 'A distant meow. It sounds judgmental.', 'You hear a box being sat in.']), 3.5);
345:       }
346:     }
347:   }
348: 
349:   updateScheduled(npc, dt, night, hour) {
350:     const game = this.game;
351:     npc.attackCd = Math.max(0, npc.attackCd - dt);
352:     let target = npc.work;
353:     if (night) target = npc.home;
354:     else if (hour < 8 || hour > 19) target = npc.home;
355:     const tx = target.x, tz = target.z;
356:     const dx = tx - npc.group.position.x, dz = tz - npc.group.position.z;
357:     const dist = Math.hypot(dx, dz);
358:     if (dist > 1.3) {
359:       npc.sleeping = false; npc.sitting = false;
360:       const speed = 1.35;
361:       npc.facing = Math.atan2(dx, dz);
362:       let nx = npc.group.position.x + (dx / dist) * speed * dt;
363:       let nz = npc.group.position.z + (dz / dist) * speed * dt;
364:       if (game.world.collidesCircle(nx, nz, 0.45)) {
365:         // sidestep
366:         const a = npc.facing + Math.PI / 2;
367:         nx = npc.group.position.x + Math.sin(a) * speed * dt;
368:         nz = npc.group.position.z + Math.cos(a) * speed * dt;
369:         npc.stuck += dt;
370:         if (npc.stuck > 3) { npc.group.position.set(tx, game.world.groundHeight(tx, tz), tz); npc.stuck = 0; }
371:       }
372:       npc.group.position.x = nx; npc.group.position.z = nz;
373:       npc.group.position.y = game.world.groundHeight(nx, nz);
374:       npc.speed = speed;
375:       npc.state = 'walk';
376:     } else {
377:       npc.speed = 0;
378:       npc.state = 'idle';
379:       npc.sitting = night || hour > 20;
380:       npc.sleeping = night;
381:       if (npc.sleeping) npc.facing = npc.home.rot || npc.facing;
382:       // face plaza / random
383:       if (!npc.sitting && Math.random() < dt * 0.4) npc.facing += this.rng.range(-1.2, 1.2);
384:     }
385:   }
386: 
387:   updateAmbient(npc, dt, night, hour) {
388:     const game = this.game;
389:     npc.speed = 0;
390:     if (night) { npc.sitting = true; npc.sleeping = true; return; }
391:     npc.sleeping = false;
392:     npc.idleT -= dt;
393:     if (npc.idleT <= 0) {
394:       npc.idleT = this.rng.range(3, 9);
395:       const w = npc.wander || { x: npc.home.x, z: npc.home.z, r: 8 };
396:       npc.wanderTarget = { x: w.x + this.rng.range(-w.r, w.r), z: w.z + this.rng.range(-w.r, w.r) };
397:       npc.sitting = this.rng.chance(0.35);
398:     }
399:     if (npc.wanderTarget && !npc.sitting) {
400:       const dx = npc.wanderTarget.x - npc.group.position.x, dz = npc.wanderTarget.z - npc.group.position.z;
401:       const d = Math.hypot(dx, dz);
402:       if (d > 0.6) {
403:         npc.facing = Math.atan2(dx, dz);
404:         const nx = npc.group.position.x + Math.sin(npc.facing) * 1.1 * dt;
405:         const nz = npc.group.position.z + Math.cos(npc.facing) * 1.1 * dt;
406:         if (!game.world.collidesCircle(nx, nz, 0.4)) {
407:           npc.group.position.set(nx, game.world.groundHeight(nx, nz), nz);
408:           npc.speed = 1.1;
409:         } else npc.idleT = 0;
410:       } else { npc.speed = 0; npc.sitting = true; }
411:     }
412:   }
413: 
414:   updateGuard(npc, dt, enemy) {
415:     const game = this.game;
416:     npc.attackCd = Math.max(0, npc.attackCd - dt);
417:     const dx = enemy.group.position.x - npc.group.position.x, dz = enemy.group.position.z - npc.group.position.z;
418:     const d = Math.hypot(dx, dz);
419:     npc.facing = Math.atan2(dx, dz);
420:     if (d > 2.2) {
421:       const nx = npc.group.position.x + (dx / d) * 2.0 * dt;
422:       const nz = npc.group.position.z + (dz / d) * 2.0 * dt;
423:       npc.group.position.set(nx, game.world.groundHeight(nx, nz), nz);
424:       npc.speed = 2.0; npc.sitting = false; npc.sleeping = false;
425:     } else {
426:       npc.speed = 0;
427:       if (npc.attackCd <= 0) {
428:         npc.attackCd = 1.3;
429:         npc.cat.playAttack();
430:         game.audio.playSword();
431:         enemy.takeDamage(10, npc);
432:         game.effects.spark(enemy.group.position.clone().add(new THREE.Vector3(0, 1, 0)), 0xffd7a0);
433:       }
434:     }
435:   }
436: 
437:   updateCompanion(npc, dt, nearestEnemy) {
438:     const game = this.game;
439:     if (npc.downed > 0) {
440:       npc.downed -= dt; npc.sitting = true; npc.speed = 0;
441:       return;
442:     }
443:     npc.sitting = false; npc.sleeping = false;
444:     npc.attackCd = Math.max(0, npc.attackCd - dt);
445:     npc.healCd = Math.max(0, (npc.healCd || 0) - dt);
446:     const p = game.player.position;
447:     const enemy = this.findEnemyFor(npc, 16);
448:     if (enemy) {
449:       const dx = enemy.group.position.x - npc.group.position.x, dz = enemy.group.position.z - npc.group.position.z;
450:       const d = Math.hypot(dx, dz);
451:       npc.facing = Math.atan2(dx, dz);
452:       if (d > (npc.companionType === 'mage' ? 7 : 2.2)) {
453:         const nx = npc.group.position.x + (dx / d) * 3.2 * dt;
454:         const nz = npc.group.position.z + (dz / d) * 3.2 * dt;
455:         if (!game.world.collidesCircle(nx, nz, 0.4)) npc.group.position.set(nx, game.world.groundHeight(nx, nz), nz);
456:         npc.speed = 3.2;
457:       } else {
458:         npc.speed = 0;
459:         if (npc.attackCd <= 0) {
460:           npc.attackCd = npc.companionType === 'mage' ? 1.9 : 1.1;
461:           if (npc.companionType === 'mage') {
462:             npc.cat.playCast();
