30:   for (let i = 0; i < n; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
31:   geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
32:   return geo;
33: }
