35: function part(list, geo, hex, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
36:   geo.scale(scale[0], scale[1], scale[2]);
37:   if (rot[0] || rot[1] || rot[2]) geo.rotateX(rot[0]), geo.rotateY(rot[1]), geo.rotateZ(rot[2]);
38:   geo.translate(pos[0], pos[1], pos[2]);
39:   paint(geo, hex);
40:   list.push(geo);
41:   return geo;
42: }
43: 
44: function sphere(list, hex, pos, r, seg = 8, scale = [1, 1, 1], rot = [0, 0, 0]) {
45:   return part(list, new THREE.SphereGeometry(r, seg, Math.max(5, seg - 2)), hex, pos, rot, scale);
46: }
47: function capsule(list, hex, pos, r, len, scale = [1, 1, 1], rot = [0, 0, 0]) {
48:   return part(list, new THREE.CapsuleGeometry(r, len, 3, 7), hex, pos, rot, scale);
49: }
50: function box(list, hex, pos, size, rot = [0, 0, 0]) {
51:   return part(list, new THREE.BoxGeometry(size[0], size[1], size[2]), hex, pos, rot);
52: }
53: function cone(list, hex, pos, r, h, seg = 5, rot = [0, 0, 0], scale = [1, 1, 1]) {
54:   return part(list, new THREE.ConeGeometry(r, h, seg), hex, pos, rot, scale);
55: }
56: function cyl(list, hex, pos, rt, rb, h, seg = 7, rot = [0, 0, 0]) {
57:   return part(list, new THREE.CylinderGeometry(rt, rb, h, seg), hex, pos, rot);
58: }
59: function merge(list) {
60:   if (!list.length) return null;
61:   const g = mergeGeometries(list, false);
62:   list.forEach(x => x.dispose());
63:   return g;
64: }
