139: // ---------------------------------------------------------------------------
140: export function createCat(opts = {}) {
141:   const breed = BREEDS.find(b => b.id === opts.breed) || BREEDS[2];
142:   const fur = FURS.find(f => f.id === opts.fur) || FURS[0];
143:   const eye = EYES.find(e => e.id === opts.eye) || EYES[0];
144:   const scale = (opts.scale || 1) * breed.scale;
145:   const isPlayer = !!opts.isPlayer;
146: 
147:   const root = new THREE.Group();
148:   root.scale.setScalar(scale);
149:   const rig = new THREE.Group();
150:   root.add(rig);
151: 
152:   const base = fur.base, hi = fur.hi, dark = fur.dark;
153:   const sock = breed.socks ? '#e9e4d8' : hi;
154:   const pointDark = breed.darkPoints ? dark : base;
155: 
156:   // --- body + hips + neck -------------------------------------------------
157:   const bodyParts = [];
158:   sphere(bodyParts, base, [0, 1.06, 0], 0.3, 9, [1.16, 1.05, 0.92]);
159:   sphere(bodyParts, base, [0, 0.84, 0], 0.27, 9, [1.1, 0.8, 0.95]);
160:   sphere(bodyParts, hi, [0, 1.1, 0.16], 0.21, 8, [0.9, 0.95, 0.5]); // chest fluff
161:   if (breed.fluff > 1.1) {
162:     sphere(bodyParts, hi, [0, 1.33, 0.02], 0.22, 8, [1.15, 0.55, 1.0]); // neck ruff
163:     sphere(bodyParts, hi, [0, 0.9, -0.2], 0.2, 8, [1.2, 0.8, 0.7]);
164:   }
165:   if (breed.stripes) {
166:     for (let i = 0; i < 3; i++) {
167:       box(bodyParts, dark, [0, 1.16 - i * 0.14, 0.285], [0.36 - i * 0.04, 0.035, 0.02], [0, 0, (i % 2 ? 0.08 : -0.08)]);
168:     }
169:     box(bodyParts, dark, [0.18, 1.3, 0.14], [0.08, 0.2, 0.04], [0, 0, 0.3]);
170:     box(bodyParts, dark, [-0.18, 1.3, 0.14], [0.08, 0.2, 0.04], [0, 0, -0.3]);
171:   }
172:   if (breed.patches) {
173:     sphere(bodyParts, '#e9e2d2', [-0.17, 1.1, 0.17], 0.17, 7, [0.8, 1.1, 0.5]);
174:     sphere(bodyParts, '#3a3130', [0.19, 0.97, 0.16], 0.15, 7, [0.9, 0.8, 0.5]);
175:     sphere(bodyParts, '#c96b3a', [0.08, 1.28, 0.12], 0.13, 7, [1, 0.7, 0.5]);
176:   }
177:   const bodyMesh = new THREE.Mesh(merge(bodyParts), catMaterial);
178:   bodyMesh.castShadow = true; bodyMesh.receiveShadow = true;
179:   rig.add(bodyMesh);
180: 
181:   // --- head ---------------------------------------------------------------
182:   const head = new THREE.Group();
183:   head.position.set(0, 1.5, 0.01);
184:   rig.add(head);
185:   const headParts = [];
186:   sphere(headParts, base, [0, 0.04, 0], 0.285, 10, [1, 0.95, 0.92]);
187:   sphere(headParts, hi, [0, -0.01, 0.2], 0.15, 8, [1.2, 0.68, 0.85]); // muzzle
188:   sphere(headParts, hi, [0.15, -0.02, 0.15], 0.1, 7, [0.9, 0.75, 0.7]);
189:   sphere(headParts, hi, [-0.15, -0.02, 0.15], 0.1, 7, [0.9, 0.75, 0.7]);
190:   sphere(headParts, '#2a1a18', [0, 0.02, 0.318], 0.042, 6, [1.15, 0.75, 0.6]); // nose
191:   box(headParts, dark, [0, -0.075, 0.315], [0.018, 0.055, 0.02]); // mouth line
192:   // cheek fluff
193:   if (breed.fluff > 1.0) {
194:     cone(headParts, hi, [0.25, -0.03, 0.08], 0.09, 0.2, 4, [0, 0, -1.1]);
195:     cone(headParts, hi, [-0.25, -0.03, 0.08], 0.09, 0.2, 4, [0, 0, 1.1]);
196:   }
197:   // ears
198:   const earX = 0.17, earY = 0.29;
199:   cone(headParts, pointDark, [earX, earY, -0.01], 0.135, 0.27, 4, [0, 0.4, -0.22]);
200:   cone(headParts, pointDark, [-earX, earY, -0.01], 0.135, 0.27, 4, [0, -0.4, 0.22]);
201:   cone(headParts, '#d68f8b', [earX - 0.005, earY - 0.015, 0.035], 0.08, 0.16, 4, [0, 0.4, -0.22]);
202:   cone(headParts, '#d68f8b', [-earX + 0.005, earY - 0.015, 0.035], 0.08, 0.16, 4, [0, -0.4, 0.22]);
203:   if (breed.tufts) {
204:     cone(headParts, hi, [earX + 0.03, earY + 0.13, 0], 0.035, 0.12, 4, [0, 0, -0.35]);
205:     cone(headParts, hi, [-earX - 0.03, earY + 0.13, 0], 0.035, 0.12, 4, [0, 0, 0.35]);
206:   }
207:   // brow patches
208:   box(headParts, dark, [0.12, 0.135, 0.255], [0.1, 0.022, 0.02], [0, 0, -0.2]);
209:   box(headParts, dark, [-0.12, 0.135, 0.255], [0.1, 0.022, 0.02], [0, 0, 0.2]);
210:   if (breed.darkPoints) {
211:     sphere(headParts, dark, [0, 0.02, 0.27], 0.11, 7, [1.25, 0.9, 0.45]);
212:     cone(headParts, dark, [earX, earY, -0.01], 0.14, 0.28, 4, [0, 0.4, -0.22]);
213:     cone(headParts, dark, [-earX, earY, -0.01], 0.14, 0.28, 4, [0, -0.4, 0.22]);
214:   }
215:   const headMesh = new THREE.Mesh(merge(headParts), catMaterial);
216:   headMesh.castShadow = true;
217:   head.add(headMesh);
218: 
219:   // eyes (unlit, expressive)
220:   const eyeGeoList = [];
221:   sphere(eyeGeoList, eye.color, [0.112, 0.08, 0.252], 0.068, 7, [1, 1.18, 0.42]);
222:   sphere(eyeGeoList, eye.color, [-0.112, 0.08, 0.252], 0.068, 7, [1, 1.18, 0.42]);
223:   box(eyeGeoList, '#0b0b0d', [0.112, 0.08, 0.282], [0.018, 0.09, 0.012]);
224:   box(eyeGeoList, '#0b0b0d', [-0.112, 0.08, 0.282], [0.018, 0.09, 0.012]);
225:   sphere(eyeGeoList, '#ffffff', [0.132, 0.112, 0.288], 0.014, 5, [1, 1, 0.4]);
226:   sphere(eyeGeoList, '#ffffff', [-0.092, 0.112, 0.288], 0.014, 5, [1, 1, 0.4]);
227:   const eyeMesh = new THREE.Mesh(merge(eyeGeoList), eyeMaterial);
228:   head.add(eyeMesh);
229: 
230:   // whiskers
231:   const wPts = [];
232:   for (const s of [-1, 1]) {
233:     for (let i = 0; i < 3; i++) {
234:       const y = -0.03 + i * 0.035;
235:       wPts.push(new THREE.Vector3(s * 0.15, y, 0.3));
236:       wPts.push(new THREE.Vector3(s * (0.4 + i * 0.03), y + 0.03 - i * 0.02, 0.24 + i * 0.015));
237:     }
238:   }
239:   const whiskers = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(wPts), whiskerMaterial);
240:   head.add(whiskers);
241: 
242:   // mouth (visible when talking)
243:   const mouth = new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 5), new THREE.MeshBasicMaterial({ color: 0x401f22 }));
244:   mouth.scale.set(1, 0.5, 0.4); mouth.position.set(0, -0.075, 0.318); mouth.visible = false;
245:   head.add(mouth);
