247:   // --- arms ---------------------------------------------------------------
248:   function makeArm(side) {
249:     const pivot = new THREE.Group();
250:     pivot.position.set(side * 0.33, 1.28, 0);
251:     const parts = [];
252:     capsule(parts, base, [0, -0.16, 0], 0.085, 0.2, [1, 1, 0.95]);
253:     capsule(parts, side > 0 ? base : hi, [0, -0.4, 0.025], 0.07, 0.19, [1, 1, 0.95]);
254:     sphere(parts, sock, [0, -0.57, 0.04], 0.09, 7, [1, 0.8, 1.05]);
255:     for (let i = -1; i <= 1; i++) {
256:       const claw = new THREE.ConeGeometry(0.011, 0.055, 4);
257:       claw.rotateX(Math.PI * 0.55); claw.translate(i * 0.026, -0.61, 0.13);
258:       paint(claw, '#efe8da'); parts.push(claw);
259:     }
260:     const mesh = new THREE.Mesh(merge(parts), catMaterial);
261:     mesh.castShadow = true;
262:     pivot.add(mesh);
263:     rig.add(pivot);
264:     return pivot;
265:   }
266:   const armR = makeArm(1), armL = makeArm(-1);
267:   armR.rotation.z = -0.12; armL.rotation.z = 0.12;
