269:   // --- legs ---------------------------------------------------------------
270:   function makeLeg(side) {
271:     const pivot = new THREE.Group();
272:     pivot.position.set(side * 0.155, 0.86, 0);
273:     const parts = [];
274:     capsule(parts, base, [0, -0.19, 0.01], 0.11, 0.2, [1, 1, 0.95]);
275:     capsule(parts, base, [0, -0.46, 0.03], 0.08, 0.21, [1, 1, 0.9]);
276:     sphere(parts, sock, [0, -0.71, 0.075], 0.1, 7, [1, 0.62, 1.5]);
