292:   capsule(tailParts, base, [0, 0.16, -0.3], 0.055 * tw, 0.18, [1, 1, 1], [1.05, 0, 0]);
293:   capsule(tailParts, pointDark, [0, 0.36, -0.42], 0.05 * tw, 0.17, [1, 1, 1], [1.4, 0, 0]);
294:   sphere(tailParts, pointDark, [0, 0.5, -0.47], 0.06 * tw, 6, [1, 1.2, 1]);
