336:       for (const s of [-1, 1]) { box(parts, '#d6b36a', [s * 0.3, 0.72, 0.08], [0.02, 0.5, 0.02]); }
337:     } else {
338:       const col = itemId === 'wardenArmor' ? '#7d9aa8' : itemId === 'ironArmor' ? '#8a9397' : '#6b4b32';
339:       const trim = itemId === 'wardenArmor' ? '#cfe6ef' : '#b08d5a';
340:       sphere(parts, col, [0, 1.08, 0.02], 0.31, 8, [1.05, 0.9, 1.0]);
341:       box(parts, trim, [0, 0.98, 0.26], [0.5, 0.06, 0.03]);
342:       sphere(parts, col, [0.33, 1.3, 0], 0.13, 6, [1, 0.7, 1]);
343:       sphere(parts, col, [-0.33, 1.3, 0], 0.13, 6, [1, 0.7, 1]);
344:       if (itemId === 'wardenArmor') {
