372:   // -----------------------------------------------------------------------
373:   const anim = {
374:     phase: Math.random() * 10, t: Math.random() * 10,
375:     attack: 0, hurt: 0, cast: 0, talk: 0, dead: 0, sit: 0, sleep: 0,
376:     blink: 2 + Math.random() * 4, blinkT: 0, speed: 0, block: 0, aim: 0,
377:   };
378: 
379:   const cat = {
380:     root, rig, head, bodyMesh, headMesh, eyeMesh, mouth, armR, armL, legR, legL,
381:     tailPivot, gear, handAnchor, backAnchor, anim, scale,
382:     breed, fur, eye, isPlayer,
383:     weaponItem: null, armorItem: null, bowItem: null,
384:     setWeapon, setArmor, setBow, setScarf,
385:     setAppearance(o) {
386:       // rebuild is handled by creator using a fresh cat
387:     },
388:     playAttack() { anim.attack = 0.42; },
389:     playCast() { anim.cast = 0.55; },
390:     playHurt() { anim.hurt = 0.3; },
391:     playTalk() { anim.talk = 0.16; },
392:     die() { anim.dead = 1; },
393:     revive() { anim.dead = 0; },
394:     setVisible(v) { root.visible = v; },
395:     update(dt, s = {}) {
396:       anim.t += dt;
397:       anim.attack = Math.max(0, anim.attack - dt);
398:       anim.hurt = Math.max(0, anim.hurt - dt);
399:       anim.cast = Math.max(0, anim.cast - dt);
