40:     h += (fbm(x * 0.04, z * 0.04, s + 9, 2) - 0.5) * 1.1;
41:     const r = Math.hypot(x, z) / this.half;
42:     const mountain = smoothstep(0.56, 1.02, r);
43:     h += mountain * (34 + ridged(x * 0.006 + 3, z * 0.006 - 2, s + 21, 5) * 104);
44:     h += smoothstep(0.78, 1.0, r) * ridged(x * 0.018, z * 0.018, s + 77, 3) * 26;
45:     // Lake in the western lowlands
46:     const lake = Math.hypot(x + 300, z - 300);
47:     h -= (1 - smoothstep(62, 155, lake)) * 11;
48:     // River valley
49:     const rx = riverX(z);
50:     const rd = Math.abs(x - rx);
51:     h -= (1 - smoothstep(3, 30, rd)) * 19;
52:     h -= (1 - smoothstep(30, 62, rd)) * 2.4;
53:     return h;
54:   }
