56:   heightAt(x, z) {
57:     let h = this.baseHeight(x, z);
58:     for (const f of this.flats) {
59:       const d = Math.hypot(x - f.x, z - f.z);
60:       if (d < f.r * 1.7) {
61:         const t = 1 - smoothstep(f.r * 0.62, f.r * 1.55, d);
62:         h = lerp(h, f.h, t * 0.94);
63:       }
64:     }
65:     // River carves through after flats so the water still runs
66:     const rx = riverX(z);
67:     const rd = Math.abs(x - rx);
68:     const riverCut = (1 - smoothstep(4, 26, rd));
69:     if (riverCut > 0.01) {
70:       let nearFlat = 0;
71:       for (const f of this.flats) {
72:         const d = Math.hypot(x - f.x, z - f.z);
73:         if (d < f.r * 1.35) nearFlat = Math.max(nearFlat, 1 - smoothstep(f.r * 0.8, f.r * 1.35, d));
74:       }
75:       h -= riverCut * 14 * (1 - nearFlat * 0.55);
76:     }
77:     return h;
78:   }
