80:   slopeAt(x, z) {
81:     const e = 1.4;
82:     const hx = this.heightAt(x + e, z) - this.heightAt(x - e, z);
83:     const hz = this.heightAt(x, z + e) - this.heightAt(x, z - e);
84:     return Math.hypot(hx, hz) / (e * 2);
