148:   buildWater() {
149:     const geo = new THREE.PlaneGeometry(WORLD_SIZE + 120, WORLD_SIZE + 120, 1, 1);
150:     geo.rotateX(-Math.PI / 2);
151:     // Procedural ripple normal map
152:     const size = 128;
153:     const data = new Uint8Array(size * size * 4);
154:     for (let y = 0; y < size; y++) {
155:       for (let x = 0; x < size; x++) {
156:         const i = (y * size + x) * 4;
157:         const nx = Math.sin(x * 0.32 + y * 0.13) * 0.5 + Math.sin(x * 0.11 - y * 0.27) * 0.5;
158:         const ny = Math.cos(x * 0.17 - y * 0.29) * 0.5 + Math.cos(x * 0.09 + y * 0.21) * 0.5;
159:         data[i] = 128 + nx * 45; data[i + 1] = 128 + ny * 45; data[i + 2] = 255; data[i + 3] = 255;
160:       }
161:     }
