180:   buildRoads() {
181:     const routes = [
182:       [[175, 306], [120, 270], [40, 220], [-40, 170]],
183:       [[-40, 170], [-140, 100], [-230, -40], [-280, -160]],
184:       [[-280, -160], [-350, -40], [-392, 138]],
185:       [[-280, -160], [-80, -220], [120, -270], [238, -292]],
186:       [[175, 306], [270, 280], [330, 240], [352, 206]],
187:       [[352, 206], [390, 60], [410, -150], [392, -356]],
188:       [[238, -292], [300, -330], [392, -356]],
189:       [[-40, 170], [-20, 20], [-10, -180], [-25, -400], [-40, -590]],
190:       [[175, 306], [230, 210], [258, 72]],
191:       [[-280, -160], [-320, -240], [-360, -344]],
192:       [[175, 306], [30, 330], [-126, 336]],
193:       [[238, -292], [190, -380], [40, -470], [-40, -590]],
194:     ];
195:     const geos = [];
196:     const color = new THREE.Color('#6d6250');
197:     this.roadPoints = [];
198:     for (const route of routes) {
199:       const pts = route.map(([x, z]) => new THREE.Vector3(x, 0, z));
200:       const curve = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.35);
201:       const steps = Math.max(30, Math.floor(curve.getLength() / 4));
202:       const verts = [], cols = [], idx = [];
203:       const width = 3.2;
204:       for (let i = 0; i <= steps; i++) {
205:         const t = i / steps;
206:         const p = curve.getPoint(t);
207:         if (i % 4 === 0) this.roadPoints.push(p);
208:         const p2 = curve.getPoint(Math.min(1, t + 0.002));
209:         const dx = p2.x - p.x, dz = p2.z - p.z;
210:         const len = Math.hypot(dx, dz) || 1;
211:         const nx = -dz / len, nz = dx / len;
212:         for (const s of [-1, 1]) {
213:           const x = p.x + nx * width * s, z = p.z + nz * width * s;
214:           const y = this.heightAt(x, z) + 0.1;
215:           verts.push(x, y, z);
216:           const shade = 0.9 + (i % 3) * 0.035;
217:           cols.push(color.r * shade, color.g * shade, color.b * shade);
218:         }
219:         if (i < steps) {
220:           const a = i * 2;
221:           idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
222:         }
223:       }
224:       const g = new THREE.BufferGeometry();
225:       g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
226:       g.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
227:       g.setIndex(idx);
228:       g.computeVertexNormals();
229:       geos.push(g);
230:     }
231:     const merged = mergeGeos(geos);
232:     const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -1 });
233:     const mesh = new THREE.Mesh(merged, mat);
234:     mesh.receiveShadow = true;
235:     mesh.name = 'roads';
236:     return mesh;
237:   }
238: }
