240: function mergeGeos(geos) {
241:   let total = 0;
242:   for (const g of geos) total += g.attributes.position.count;
243:   const pos = new Float32Array(total * 3), col = new Float32Array(total * 3);
244:   const index = [];
245:   let off = 0, vOff = 0;
246:   for (const g of geos) {
247:     pos.set(g.attributes.position.array, off * 3);
248:     col.set(g.attributes.color.array, off * 3);
249:     const gi = g.index.array;
250:     for (let i = 0; i < gi.length; i++) index.push(gi[i] + vOff);
251:     off += g.attributes.position.count;
252:     vOff += g.attributes.position.count;
253:   }
254:   const out = new THREE.BufferGeometry();
255:   out.setAttribute('position', new THREE.BufferAttribute(pos, 3));
256:   out.setAttribute('color', new THREE.BufferAttribute(col, 3));
257:   out.setIndex(index);
258:   out.computeVertexNormals();
259:   return out;
260: }
