263: export function makeSky() {
264:   const geo = new THREE.SphereGeometry(1600, 32, 20);
265:   const uniforms = {
266:     topColor: { value: new THREE.Color('#1c4257') },
267:     horizonColor: { value: new THREE.Color('#b9cdd6') },
268:     bottomColor: { value: new THREE.Color('#6d8794') },
269:     sunColor: { value: new THREE.Color('#ffd9a0') },
270:     sunDir: { value: new THREE.Vector3(0.4, 0.5, 0.2) },
271:     night: { value: 0 },
272:     time: { value: 0 },
273:   };
274:   const mat = new THREE.ShaderMaterial({
275:     side: THREE.BackSide, depthWrite: false, fog: false, uniforms,
276:     vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
277:     fragmentShader: `
278:       varying vec3 vDir; uniform vec3 topColor,horizonColor,bottomColor,sunColor,sunDir; uniform float night,time;
279:       void main(){
280:         float y = clamp(vDir.y*0.5+0.5,0.0,1.0);
281:         vec3 col = mix(bottomColor,horizonColor,smoothstep(0.38,0.52,y));
282:         col = mix(col,topColor,smoothstep(0.5,0.92,y));
283:         float sun = max(dot(normalize(vDir),normalize(sunDir)),0.0);
284:         col += sunColor*pow(sun,180.0)*1.6;
285:         col += sunColor*pow(sun,8.0)*0.18;
286:         // faint moving cloud bands
287:         float band = sin(vDir.x*6.0+vDir.z*4.0+time*0.03)*0.5+0.5;
288:         band *= smoothstep(0.35,0.6,y)*(1.0-smoothstep(0.75,0.95,y));
289:         col = mix(col, vec3(0.82,0.86,0.9), band*0.08*(1.0-night));
290:         // night blue
291:         vec3 ncol = mix(vec3(0.02,0.035,0.08),vec3(0.05,0.08,0.14),y);
292:         col = mix(col,ncol,night*0.92);
293:         gl_FragColor = vec4(col,1.0);
294:       }`,
295:   });
296:   const mesh = new THREE.Mesh(geo, mat);
297:   mesh.frustumCulled = false;
298:   mesh.renderOrder = -10;
299:   return { mesh, uniforms };
300: }
