314:   geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
315:   const mat = new THREE.PointsMaterial({ color: 0xdfe9ff, size: 2.2, transparent: true, opacity: 0, depthWrite: false, sizeAttenuation: false, fog: false });
316:   const points = new THREE.Points(geo, mat);
317:   points.frustumCulled = false;
318:   points.renderOrder = -9;
319:   return points;
