226: #photo-badge{position:absolute;left:50%;top:calc(18px + var(--safe-t));transform:translateX(-50%);font:700 9px var(--sans);letter-spacing:.3em;color:var(--gold);border:1px solid var(--line);padding:5px 12px;z-index:12;background:rgba(5,10,13,.6)}
227: 
228: /* ============ DIALOGUE ============ */
229: #dialogue.show{display:block;background:linear-gradient(180deg,transparent 45%,rgba(2,6,9,.72));backdrop-filter:none;padding:0}
230: .dialogue-box{position:absolute;left:50%;bottom:calc(26px + var(--safe-b));transform:translateX(-50%);width:min(900px,94vw);display:flex;gap:18px;padding:20px 24px;background:linear-gradient(180deg,rgba(11,22,29,.97),rgba(7,14,19,.98));border:1px solid var(--line);box-shadow:0 20px 70px rgba(0,0,0,.65),inset 0 1px 0 rgba(255,255,255,.05);animation:dlgIn .22s ease both}
231: @keyframes dlgIn{from{opacity:0;transform:translate(-50%,10px)}to{opacity:1;transform:translate(-50%,0)}}
232: .dialogue-box:before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:linear-gradient(180deg,var(--gold),transparent)}
233: .dlg-portrait{flex:0 0 72px}
234: .dlg-portrait .cat-avatar{width:72px;height:72px;box-shadow:inset 0 0 16px rgba(0,0,0,.6),0 0 0 3px rgba(8,14,18,.8),0 0 24px rgba(216,177,106,.12)}
235: .dlg-main{flex:1;min-width:0}
236: .dlg-name{font:700 15px var(--serif);letter-spacing:.12em;color:var(--gold-hi);margin-bottom:7px}
237: .dlg-text{font:15px/1.55 var(--sans);color:#d4e4eb;margin:0 0 13px;min-height:44px}
238: .dlg-text em{color:var(--gold);font-style:italic}
239: .dlg-options{display:flex;flex-direction:column;gap:4px}
240: .dlg-opt{text-align:left;padding:7px 11px;background:rgba(18,33,41,.5);border-left:1px solid rgba(216,177,106,.3);font:13px var(--sans);color:#c6dae3;transition:.13s}
241: .dlg-opt:hover{background:rgba(40,74,84,.55);border-left-color:var(--gold-hi);color:#fff;padding-left:15px}
242: .dlg-opt .tag{font:8px var(--sans);letter-spacing:.1em;color:var(--gold);margin-left:8px;border:1px solid rgba(216,177,106,.3);padding:1px 4px}
243: .dlg-opt .tag.quest{color:#8fd3a8;border-color:rgba(143,211,168,.35)}
244: .dlg-opt .tag.shop{color:#e0c482;border-color:rgba(224,196,130,.35)}
245: .close-x{position:absolute;right:8px;top:8px;width:26px;height:26px;font:14px var(--sans);color:#78909c;display:grid;place-items:center}
246: .close-x:hover{color:var(--frost)}
247: 
248: /* ============ PANELS ============ */
249: .panel{width:min(980px,96vw);max-height:90vh;display:flex;flex-direction:column;background:linear-gradient(180deg,rgba(12,23,30,.98),rgba(7,14,19,.99));border:1px solid var(--line);box-shadow:0 30px 100px rgba(0,0,0,.7),inset 0 1px 0 rgba(255,255,255,.04);position:relative}
250: .panel:before{content:'';position:absolute;inset:6px;border:1px solid rgba(232,244,250,.045);pointer-events:none}
251: .panel.wide{width:min(1180px,96vw)}
252: .panel-head{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 26px 15px;border-bottom:1px solid var(--line-soft);position:relative}
253: .panel-head .eyebrow{font:700 9px var(--sans);letter-spacing:.3em;color:var(--gold);text-transform:uppercase}
254: .panel-head h2{font:700 clamp(24px,3vw,34px)/1.05 var(--serif);margin:4px 0 0;letter-spacing:.05em}
255: .panel-resources{display:flex;align-items:center;gap:8px;font:700 16px var(--serif);color:var(--gold-hi);margin-left:auto;margin-right:34px}
256: .panel-resources .cap{font:10px var(--sans);color:var(--muted);letter-spacing:.08em;margin-left:8px}
257: .panel-resources .cap b{color:var(--frost-dim)}
258: .panel-foot{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 26px;border-top:1px solid var(--line-soft);font:italic 12px var(--sans);color:var(--muted)}
259: .panel-foot .btn{font-style:normal}
260: .skill-points{margin-left:auto;margin-right:34px;font:12px var(--sans);color:var(--muted);letter-spacing:.08em}
261: .skill-points b{color:var(--gold-hi);font:700 22px var(--serif);margin-left:6px}
262: 
263: /* inventory */
264: .inv-body{display:grid;grid-template-columns:300px 1fr;gap:0;min-height:0;flex:1;overflow:hidden}
265: .equipment{padding:18px 22px;border-right:1px solid var(--line-soft);overflow:auto}
266: .equipment h3,.bag h3{font:700 10px var(--sans);letter-spacing:.24em;color:var(--muted);text-transform:uppercase;margin:0 0 12px}
267: .equip-slots{display:grid;grid-template-columns:1fr 1fr;gap:8px}
268: .equip-slot{position:relative;height:76px;border:1px solid var(--line-soft);background:rgba(5,11,15,.45);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;transition:.15s;cursor:pointer}
269: .equip-slot:hover{border-color:var(--gold-dim)}
270: .slot-label{position:absolute;left:6px;top:4px;font:7px var(--sans);letter-spacing:.15em;color:var(--muted);text-transform:uppercase}
271: .equip-ico{color:var(--gold);display:flex}
272: .equip-ico svg{width:32px;height:32px}
273: .equip-ico .empty{font:10px var(--sans);color:#4f646e;letter-spacing:.05em}
274: .equip-slot b{font:10px var(--sans);color:#b7cbd5;text-align:center;padding:0 4px;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
275: .stats-card{margin-top:18px;border-top:1px solid var(--line-soft);padding-top:12px}
276: .stats-card h3{margin-bottom:8px}
277: .stat-row{display:flex;justify-content:space-between;font:12px var(--sans);color:#a7bcc6;padding:3px 0;border-bottom:1px dotted rgba(255,255,255,.05)}
278: .stat-row b{color:var(--frost);font-weight:500}
279: .bag{padding:18px 22px;display:flex;flex-direction:column;min-height:0}
280: .bag-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
281: .bag-head h3{margin:0}
282: .tabs{display:flex;gap:3px}
283: .tabs button{font:10px var(--sans);letter-spacing:.08em;color:var(--muted);padding:3px 8px;border:1px solid transparent}
284: .tabs button.active{color:var(--gold-hi);border-color:var(--line)}
285: .tabs button:hover{color:var(--frost)}
286: .inv-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(72px,1fr));gap:6px;overflow:auto;align-content:start;padding-right:4px;min-height:260px;max-height:52vh}
287: .inv-cell{position:relative;aspect-ratio:1;border:1px solid rgba(232,244,250,.09);background:linear-gradient(160deg,rgba(18,32,40,.65),rgba(6,12,16,.65));display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;transition:.13s;cursor:pointer;overflow:hidden}
288: .inv-cell:hover{border-color:var(--gold);background:rgba(40,70,80,.55);transform:translateY(-1px)}
289: .inv-cell.equipped{border-color:rgba(216,177,106,.5);box-shadow:inset 0 0 18px rgba(216,177,106,.08)}
290: .inv-cell .item-ico{color:#cfe3ec;display:flex}
291: .inv-cell .item-ico svg{width:26px;height:26px}
292: .inv-cell .item-name{font:8px/1.1 var(--sans);color:#a4b9c3;text-align:center;padding:0 3px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
293: .inv-cell .qty{position:absolute;right:3px;top:2px;font:700 9px var(--sans);color:var(--gold-hi);text-shadow:0 1px 2px #000}
294: .inv-cell .rarity{position:absolute;left:0;top:0;bottom:0;width:2px;background:transparent}
295: .inv-cell.rare .rarity{background:#7ba7d6}.inv-cell.epic .rarity{background:#b38ae0}.inv-cell.quest .rarity{background:var(--gold)}
296: .inv-empty{grid-column:1/-1;text-align:center;padding:40px 10px;font:italic 13px var(--sans);color:#5c717b}
297: .item-tip{position:fixed;z-index:90;width:230px;padding:10px 12px;background:rgba(5,11,15,.97);border:1px solid var(--line);pointer-events:none;box-shadow:0 10px 40px rgba(0,0,0,.6)}
298: .item-tip b{display:block;font:700 13px var(--serif);color:var(--gold-hi);margin-bottom:3px}
299: .item-tip span{display:block;font:11px/1.4 var(--sans);color:#a9bdc7}
300: .item-tip em{display:block;font:11px var(--sans);color:var(--green);font-style:normal;margin-top:4px}
301: 
302: /* skills */
303: .skill-body{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:20px 26px;overflow:auto;flex:1}
304: .skill-tree{border:1px solid var(--line-soft);background:rgba(5,11,15,.35);padding:14px}
305: .skill-tree h3{font:700 13px var(--serif);letter-spacing:.14em;color:var(--gold);margin:0 0 3px}
306: .skill-tree>p{font:italic 11px/1.4 var(--sans);color:var(--muted);margin:0 0 12px;min-height:28px}
307: .skill-node{display:flex;align-items:center;gap:10px;padding:8px;border:1px solid rgba(232,244,250,.08);margin-bottom:6px;background:rgba(13,24,31,.55);transition:.15s;width:100%;text-align:left}
308: .skill-node:hover{border-color:var(--gold-dim);background:rgba(30,55,65,.5)}
309: .skill-node.maxed{border-color:rgba(216,177,106,.3)}
310: .skill-node.locked{opacity:.45}
311: .skill-node .sn-ico{width:30px;height:30px;flex:0 0 30px;display:grid;place-items:center;border:1px solid var(--line-soft);color:var(--teal-hi)}
312: .skill-node .sn-ico svg{width:17px;height:17px}
313: .skill-node .sn-txt{flex:1;min-width:0}
314: .skill-node b{display:block;font:600 12px var(--serif);letter-spacing:.04em;color:#dceaf0}
315: .skill-node span{display:block;font:10px/1.3 var(--sans);color:var(--muted)}
316: .skill-node .pips{display:flex;gap:2px;margin-top:3px}
317: .skill-node .pips i{width:12px;height:3px;background:rgba(255,255,255,.12)}
318: .skill-node .pips i.on{background:var(--gold);box-shadow:0 0 5px rgba(216,177,106,.5)}
319: .skill-node .cost{font:700 9px var(--sans);color:var(--gold);border:1px solid var(--line);padding:2px 5px;white-space:nowrap}
320: 
321: /* quests */
322: .quest-body{display:grid;grid-template-columns:360px 1fr;min-height:400px;max-height:60vh;flex:1;overflow:hidden}
323: .quest-list{border-right:1px solid var(--line-soft);overflow:auto;padding:12px}
324: .quest-item{width:100%;text-align:left;padding:10px 12px;border-left:2px solid transparent;background:rgba(255,255,255,.015);margin-bottom:5px;transition:.15s}
325: .quest-item:hover{background:rgba(40,70,80,.35)}
326: .quest-item.active{border-left-color:var(--gold);background:rgba(40,70,80,.3)}
327: .quest-item .qtype{font:7px var(--sans);letter-spacing:.2em;color:var(--gold);text-transform:uppercase}
328: .quest-item b{display:block;font:600 13px var(--serif);color:#dceaf0;margin:2px 0}
329: .quest-item span{font:11px var(--sans);color:var(--muted)}
330: .quest-item.done{opacity:.5}
331: .quest-detail{padding:22px 26px;overflow:auto}
332: .quest-detail h3{font:700 24px var(--serif);color:var(--gold-hi);margin:0 0 4px;letter-spacing:.03em}
333: .quest-detail .qmeta{font:10px var(--sans);letter-spacing:.14em;color:var(--muted);text-transform:uppercase;margin-bottom:14px}
334: .quest-detail p{font:14px/1.6 var(--sans);color:#b9cdd6;margin:0 0 16px}
335: .quest-obj-list{list-style:none;padding:0;margin:0 0 16px}
336: .quest-obj-list li{padding:6px 0 6px 22px;position:relative;font:13px var(--sans);color:#bdd0d9;border-bottom:1px dotted rgba(255,255,255,.06)}
337: .quest-obj-list li:before{content:'';position:absolute;left:4px;top:12px;width:7px;height:7px;border:1px solid var(--gold);transform:rotate(45deg)}
338: .quest-obj-list li.done{color:#6f8794;text-decoration:line-through}
339: .quest-obj-list li.done:before{background:var(--green);border-color:var(--green)}
340: .quest-reward{font:12px var(--sans);color:var(--gold);border-top:1px solid var(--line-soft);padding-top:10px}
341: .empty-note{font:italic 14px var(--sans);color:#5c717b;padding:30px 0}
342: 
343: /* map */
344: .map-body{display:grid;grid-template-columns:1fr 280px;gap:0;flex:1;min-height:0}
345: #map-canvas{width:100%;height:min(58vh,620px);display:block;background:#081016}
346: .map-side{border-left:1px solid var(--line-soft);padding:20px;overflow:auto}
347: .map-side h3{font:700 22px var(--serif);color:var(--gold-hi);margin:0 0 4px}
348: .map-side p{font:13px/1.5 var(--sans);color:#a9bec8;margin:0 0 18px}
349: .map-markers{display:flex;flex-direction:column;gap:4px}
350: .map-marker{text-align:left;padding:6px 8px;border-left:2px solid var(--line);background:rgba(255,255,255,.02);font:12px var(--sans);color:#b8ccd5}
351: .map-marker:hover{background:rgba(40,70,80,.4);border-left-color:var(--gold)}
352: .map-marker b{display:block;font:600 12px var(--serif);color:#dceaf0}
353: .map-marker span{font:10px var(--sans);color:var(--muted)}
354: .map-legend{display:flex;gap:14px;margin-left:auto;margin-right:34px;font:10px var(--sans);color:var(--muted)}
355: .map-legend span{display:flex;align-items:center;gap:5px}
356: .lg{width:7px;height:7px;display:inline-block;transform:rotate(45deg);background:var(--gold)}
357: .lg.player{background:#fff;border-radius:50%;transform:none}.lg.main{background:var(--gold)}.lg.side{background:#7fb5c8}.lg.town{background:#c8a06b;border-radius:50%;transform:none}
358: 
359: /* shop */
360: .shop-body{display:grid;grid-template-columns:1fr 1fr;gap:0;flex:1;min-height:360px;max-height:58vh}
361: .shop-col{padding:16px 20px;overflow:auto}
362: .shop-col:first-child{border-right:1px solid var(--line-soft)}
363: .shop-col h3{font:700 10px var(--sans);letter-spacing:.22em;color:var(--muted);text-transform:uppercase;margin:0 0 10px}
364: .shop-list{display:flex;flex-direction:column;gap:5px}
365: .shop-row{display:flex;align-items:center;gap:10px;padding:7px 9px;border:1px solid rgba(232,244,250,.07);background:rgba(255,255,255,.015);transition:.13s;text-align:left;width:100%}
366: .shop-row:hover{border-color:var(--gold-dim);background:rgba(40,70,80,.35)}
367: .shop-row .item-ico{color:var(--gold);display:flex;flex:0 0 24px}
368: .shop-row .item-ico svg{width:22px;height:22px}
369: .shop-row .sr-txt{flex:1;min-width:0}
370: .shop-row b{display:block;font:600 12px var(--serif);color:#dceaf0}
371: .shop-row span{display:block;font:10px var(--sans);color:var(--muted)}
372: .shop-row .price{font:700 11px var(--serif);color:var(--gold-hi);white-space:nowrap}
373: .shop-row .price:before{content:'◆ ';font-size:7px;vertical-align:1px;color:var(--gold-dim)}
374: 
375: /* pause */
376: .pause-panel{width:min(480px,92vw);padding:34px 36px;background:linear-gradient(180deg,rgba(12,23,30,.98),rgba(6,12,16,.99));border:1px solid var(--line);text-align:center;box-shadow:0 30px 100px rgba(0,0,0,.7);position:relative}
377: .pause-crest{margin-bottom:8px}
378: .pause-panel h2{font:700 36px var(--serif);letter-spacing:.12em;margin:0 0 2px;color:var(--frost)}
379: .pause-sub{font:italic 14px var(--sans);color:var(--muted);margin:0 0 24px}
380: .pause-buttons{display:flex;flex-direction:column;gap:6px}
381: .pause-buttons .btn{width:100%}
382: .settings-box{margin-top:18px;border-top:1px solid var(--line-soft);padding-top:14px;text-align:left}
383: .setting{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:5px 0;font:12px var(--sans);color:#b3c7d1}
384: .setting input[type=range]{width:150px;accent-color:var(--gold)}
385: .setting select{background:#0a151b;border:1px solid var(--line-soft);color:var(--frost);font:11px var(--sans);padding:3px 6px}
386: .setting.check input{accent-color:var(--gold)}
387: .pause-foot{display:flex;justify-content:space-between;gap:10px;margin-top:22px;font:9px var(--sans);color:#516671;letter-spacing:.08em}
388: 
389: /* help */
390: .help-body{padding:22px 26px;overflow:auto}
391: .help-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 30px}
392: .help-grid h3{font:700 12px var(--serif);letter-spacing:.14em;color:var(--gold);margin:0 0 4px}
393: .help-grid p{font:12.5px/1.55 var(--sans);color:#a9bec8;margin:0}
394: .help-controls{display:flex;flex-wrap:wrap;gap:14px;margin-top:20px;border-top:1px solid var(--line-soft);padding-top:14px;font:11px var(--sans);color:var(--muted)}
395: 
396: /* end screens */
397: .end-panel{width:min(620px,92vw);text-align:center;padding:40px;border:1px solid var(--line);background:rgba(7,14,18,.96);box-shadow:0 30px 120px rgba(0,0,0,.8)}
398: .end-panel .eyebrow{font:700 9px var(--sans);letter-spacing:.4em;color:var(--gold);text-transform:uppercase}
399: .end-panel h2{font:900 clamp(28px,4vw,44px)/1.1 var(--serif);margin:10px 0 14px;letter-spacing:.04em}
400: .end-panel p{font:italic 15px/1.6 var(--sans);color:#b7cad3;margin:0 0 24px}
401: .victory h2{color:var(--gold-hi);text-shadow:0 0 50px rgba(216,177,106,.25)}
402: .victory-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 24px}
403: .victory-stats div{border:1px solid var(--line-soft);padding:10px;font:10px var(--sans);color:var(--muted);letter-spacing:.1em;text-transform:uppercase}
404: .victory-stats b{display:block;font:700 22px var(--serif);color:var(--gold-hi);margin-bottom:2px;letter-spacing:0}
405: 
406: /* ============ MOBILE ============ */
407: #mobile-controls{position:absolute;inset:0;z-index:9;pointer-events:none}
408: .joystick{position:absolute;left:calc(22px + env(safe-area-inset-left,0px));bottom:calc(24px + var(--safe-b));width:118px;height:118px;border-radius:50%;border:1px solid rgba(232,244,250,.2);background:rgba(6,13,17,.35);pointer-events:auto;touch-action:none}
409: .joystick:before{content:'';position:absolute;inset:17px;border-radius:50%;border:1px dashed rgba(232,244,250,.12)}
410: .joystick i{position:absolute;left:50%;top:50%;width:48px;height:48px;margin:-24px 0 0 -24px;border-radius:50%;background:radial-gradient(circle at 38% 32%,rgba(240,250,255,.75),rgba(150,190,205,.4));border:1px solid rgba(255,255,255,.5);box-shadow:0 0 20px rgba(120,200,210,.3)}
411: .touch-look{position:absolute;right:0;top:15%;width:52%;height:60%;pointer-events:auto;touch-action:none}
412: .touch-actions{position:absolute;right:calc(20px + env(safe-area-inset-right,0px));bottom:calc(28px + var(--safe-b));display:grid;grid-template-columns:repeat(2,58px);gap:9px;pointer-events:auto}
413: .tbtn{width:58px;height:58px;border-radius:50%;background:rgba(10,20,26,.65);border:1px solid rgba(216,177,106,.4);color:var(--gold-hi);font:20px var(--serif);display:grid;place-items:center;touch-action:none;backdrop-filter:blur(3px)}
414: .tbtn.attack{width:70px;height:70px;background:rgba(80,40,35,.6);border-color:rgba(224,130,110,.5);font-size:24px}
415: .tbtn.small{width:46px;height:46px;font-size:14px;justify-self:end}
416: .tbtn:active{transform:scale(.93);background:rgba(60,100,110,.7)}
417: @media (pointer:coarse){#mobile-controls.show{display:block!important}.hud-bottom-left{display:none}.hud-bottom-right{display:none}.hint-line{display:none}.interact-prompt{bottom:calc(165px + var(--safe-b))}.quest-tracker{top:calc(100px + var(--safe-t));width:min(230px,56vw)}.compass{width:100%}.hud-top-center{width:36vw;left:56%}}
418: 
419: /* ============ RESPONSIVE ============ */
420: @media(max-width:900px){
421:   .creator-body{grid-template-columns:1fr;gap:12px}
422:   .creator-preview{display:none}
423:   .creator-wrap{max-height:92vh;overflow:auto}
424:   .menu-side{display:none}
425:   .menu-inner{left:24px;width:calc(100% - 48px)}
426:   .inv-body{grid-template-columns:1fr;overflow:auto}
427:   .equipment{border-right:0;border-bottom:1px solid var(--line-soft)}
428:   .equip-slots{grid-template-columns:repeat(4,1fr)}
429:   .inv-grid{max-height:38vh}
430:   .quest-body{grid-template-columns:1fr;max-height:64vh}
431:   .quest-list{max-height:190px;border-right:0;border-bottom:1px solid var(--line-soft)}
432:   .map-body{grid-template-columns:1fr}
433:   .map-side{display:none}
434:   .skill-body{grid-template-columns:1fr}
435:   .shop-body{grid-template-columns:1fr;max-height:60vh}
