33: export class Batch {
34:   constructor() { this.buckets = new Map(); this.count = 0; }
35:   add(geo, matKey, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
36:     const m = new THREE.Matrix4();
37:     const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(rot[0], rot[1], rot[2]));
38:     m.compose(new THREE.Vector3(pos[0], pos[1], pos[2]), q, new THREE.Vector3(scale[0], scale[1], scale[2]));
39:     geo.applyMatrix4(m);
40:     if (!this.buckets.has(matKey)) this.buckets.set(matKey, []);
41:     this.buckets.get(matKey).push(geo);
42:     this.count++;
43:     return geo;
44:   }
45:   box(matKey, pos, size, rot = [0, 0, 0]) { return this.add(new THREE.BoxGeometry(size[0], size[1], size[2]), matKey, pos, rot); }
46:   cyl(matKey, pos, rTop, rBot, h, seg = 8, rot = [0, 0, 0]) { return this.add(new THREE.CylinderGeometry(rTop, rBot, h, seg), matKey, pos, rot); }
47:   sphere(matKey, pos, r, seg = 8, scale = [1, 1, 1]) { return this.add(new THREE.SphereGeometry(r, seg, Math.max(5, seg - 2)), matKey, pos, [0, 0, 0], scale); }
48:   cone(matKey, pos, r, h, seg = 8, rot = [0, 0, 0]) { return this.add(new THREE.ConeGeometry(r, h, seg), matKey, pos, rot); }
49:   build(parent, shadow = true) {
50:     for (const [key, geos] of this.buckets) {
51:       if (!geos.length) continue;
52:       const merged = mergeGeometries(geos, false);
53:       geos.forEach(g => g.dispose());
54:       const mesh = new THREE.Mesh(merged, MATS[key] || MATS.stone);
55:       mesh.castShadow = shadow && key !== 'window';
56:       mesh.receiveShadow = true;
57:       mesh.name = 'batch-' + key;
58:       parent.add(mesh);
59:     }
60:     this.buckets.clear();
61:   }
62: }
