498:     const g = this.game;
499:     const inv = g.inventory;
500:     if (!inv) return;
501:     if (this.refs.invGold) this.refs.invGold.textContent = inv.gold;
502:     if (this.refs.invWeight) this.refs.invWeight.textContent = inv.weight();
503:     const slots = { weapon: this.refs.eqWeapon, armor: this.refs.eqArmor, trinket: this.refs.eqTrinket, bow: this.refs.eqBow };
504:     for (const k in slots) {
505:       const node = slots[k];
506:       if (!node) continue;
507:       const id = inv.equipment[k];
508:       const item = ITEMS[id];
509:       node.innerHTML = item ? `${icon(item.icon)}<b>${item.name}</b>` : `<span class="empty">Empty</span>`;
510:       node.style.color = item ? '#d8b16a' : '';
511:     }
512:     const st = inv.statSummary();
513:     if (this.refs.statsCard) {
514:       this.refs.statsCard.innerHTML = [
515:         ['Damage', st.damage || 4],
516:         ['Armor', st.armor],
517:         ['Spell power', st.magic],
518:         ['Bow', st.bow || 0],
519:         ['Attack speed', st.weaponSpeed.toFixed(2) + '×'],
520:         ['Health', `${fmt(g.player.health)} / ${g.player.maxHealth}`],
521:         ['Mana', `${fmt(g.player.mana)} / ${g.player.maxMana}`],
522:         ['Stamina', `${fmt(g.player.stamina)} / ${g.player.maxStamina}`],
523:       ].map(([a, b]) => `<div class="stat-row"><span>${a}</span><b>${b}</b></div>`).join('');
524:     }
525:     const grid = this.refs.invGrid;
526:     if (!grid) return;
527:     grid.innerHTML = '';
528:     const entries = [...inv.slots.entries()].filter(([id]) => {
529:       const item = ITEMS[id];
530:       if (!item) return false;
531:       if (this.invFilter === 'all') return true;
532:       if (this.invFilter === 'potion') return item.type === 'potion' || item.type === 'food';
533:       if (this.invFilter === 'quest') return item.type === 'quest' || item.rarity === 'quest';
534:       return item.type === this.invFilter;
535:     });
536:     if (!entries.length) {
537:       grid.appendChild(el('div', 'inv-empty', 'Nothing here. A very tidy, very suspicious bag.'));
538:       return;
539:     }
540:     const order = { weapon: 0, armor: 1, bow: 2, trinket: 3, potion: 4, food: 5, quest: 6 };
541:     entries.sort((a, b) => (order[ITEMS[a[0]]?.type] ?? 9) - (order[ITEMS[b[0]]?.type] ?? 9));
542:     for (const [id, qty] of entries) {
543:       const item = ITEMS[id];
544:       if (!item) continue;
545:       const equipped = Object.values(inv.equipment).includes(id);
546:       const cell = el('div', 'inv-cell' + (equipped ? ' equipped' : '') + (item.rarity === 'rare' ? ' rare' : item.rarity === 'epic' ? ' epic' : item.rarity === 'quest' ? ' quest' : ''));
547:       cell.innerHTML = `<span class="rarity"></span>${qty > 1 ? `<span class="qty">${qty}</span>` : ''}<span class="item-ico">${icon(item.icon)}</span><span class="item-name">${item.name}</span>`;
548:       cell.title = `${item.name}\n${item.desc}`;
549:       cell.addEventListener('click', (ev) => {
550:         if (ev.shiftKey) {
551:           if (inv.remove(id, 1)) this.toast(`Dropped ${item.name}. It is someone else’s problem now.`);
552:           this.refreshInventory();
553:           return;
554:         }
555:         if (['weapon', 'armor', 'trinket', 'bow'].includes(item.type)) {
556:           inv.equip(id);
557:         } else if (item.type === 'potion' || item.type === 'food') {
558:           inv.use(id);
559:           this.updateHUD();
560:         } else {
561:           this.toast(`<b>${item.name}</b><br>${item.desc}`, item.rarity === 'quest' ? 'quest' : '');
562:         }
563:         this.refreshInventory();
564:       });
565:       grid.appendChild(cell);
566:     }
567:   }
