692:   drawMap() {
693:     const g = this.game;
694:     const canvas = this.refs.mapCanvas;
695:     if (!canvas) return;
696:     const rect = canvas.getBoundingClientRect();
697:     const dpr = Math.min(2, window.devicePixelRatio || 1);
698:     const w = Math.max(320, rect.width), h = Math.max(260, rect.height);
699:     canvas.width = w * dpr; canvas.height = h * dpr;
700:     const ctx = canvas.getContext('2d');
701:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
702:     const pad = 22;
703:     const size = Math.min(w, h) - pad * 2;
704:     const ox = (w - size) / 2, oy = (h - size) / 2;
705:     const toMap = (x, z) => [ox + ((x + 700) / 1400) * size, oy + ((z + 700) / 1400) * size];
706:     // background
707:     const bg = ctx.createRadialGradient(w / 2, h / 2, 20, w / 2, h / 2, size * 0.75);
708:     bg.addColorStop(0, '#152b34');
709:     bg.addColorStop(0.6, '#0d1c24');
710:     bg.addColorStop(1, '#070f14');
711:     ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
712:     // parchment grid
713:     ctx.strokeStyle = 'rgba(216,177,106,.08)';
714:     ctx.lineWidth = 1;
715:     for (let i = 1; i < 8; i++) {
716:       const p = ox + (i / 8) * size;
717:       ctx.beginPath(); ctx.moveTo(p, oy); ctx.lineTo(p, oy + size); ctx.stroke();
718:       const q = oy + (i / 8) * size;
719:       ctx.beginPath(); ctx.moveTo(ox, q); ctx.lineTo(ox + size, q); ctx.stroke();
720:     }
721:     // border
722:     ctx.strokeStyle = 'rgba(216,177,106,.35)';
723:     ctx.strokeRect(ox - 1, oy - 1, size + 2, size + 2);
724: 
725:     // river
726:     ctx.strokeStyle = 'rgba(100,199,201,.4)';
727:     ctx.lineWidth = 3.2;
728:     ctx.beginPath();
729:     for (let z = -700; z <= 700; z += 10) {
730:       const x = 110 * Math.sin(z * 0.0075) + 45 * Math.sin(z * 0.019 + 1.7);
731:       const [mx, my] = toMap(x, z);
732:       if (z === -700) ctx.moveTo(mx, my); else ctx.lineTo(mx, my);
733:     }
734:     ctx.stroke();
735:     // lake
736:     const [lx, ly] = toMap(-300, 300);
737:     ctx.fillStyle = 'rgba(80,150,170,.3)';
738:     ctx.beginPath(); ctx.ellipse(lx, ly, size * 0.075, size * 0.06, 0, 0, Math.PI * 2); ctx.fill();
739: 
740:     // roads
741:     if (g.world?.roadPoints?.length) {
742:       ctx.strokeStyle = 'rgba(190,170,130,.28)';
743:       ctx.lineWidth = 1.6;
744:       ctx.beginPath();
745:       let prev = null;
746:       for (const p of g.world.roadPoints) {
747:         const [mx, my] = toMap(p.x, p.z);
748:         if (!prev || Math.hypot(mx - prev[0], my - prev[1]) > size * 0.25) ctx.moveTo(mx, my);
749:         else ctx.lineTo(mx, my);
750:         prev = [mx, my];
751:       }
752:       ctx.stroke();
753:     }
754: 
755:     // mountains
756:     ctx.fillStyle = 'rgba(210,225,232,.10)';
757:     for (let i = 0; i < 60; i++) {
758:       const a = (i / 60) * Math.PI * 2;
759:       const r = 0.78 + (i % 3) * 0.04;
760:       const [mx, my] = toMap(Math.cos(a) * 700 * r, Math.sin(a) * 700 * r);
761:       ctx.beginPath(); ctx.arc(mx, my, 4 + (i % 4) * 2, 0, Math.PI * 2); ctx.fill();
762:     }
763: 
764:     // landmarks
765:     for (const key in LANDMARKS) {
766:       const l = LANDMARKS[key];
767:       if (l.radius < 30) continue;
768:       const [mx, my] = toMap(l.x, l.z);
769:       ctx.fillStyle = '#c8a06b';
770:       ctx.beginPath(); ctx.arc(mx, my, 3.4, 0, Math.PI * 2); ctx.fill();
771:       ctx.strokeStyle = 'rgba(200,160,107,.35)';
772:       ctx.beginPath(); ctx.arc(mx, my, 7, 0, Math.PI * 2); ctx.stroke();
773:       ctx.fillStyle = 'rgba(220,234,240,.7)';
774:       ctx.font = '9px "Alegreya Sans", sans-serif';
775:       ctx.textAlign = 'center';
776:       ctx.fillText(l.name.toUpperCase(), mx, my - 10);
777:     }
778: 
779:     // quest markers
780:     for (const state of g.quests.states.values()) {
781:       if (state.complete) continue;
782:       const pos = g.quests.markerPosition(state.id);
783:       if (!pos) continue;
784:       const q = QUESTS_BY_ID[state.id];
785:       const [mx, my] = toMap(pos.x, pos.z);
786:       ctx.save();
787:       ctx.translate(mx, my);
788:       ctx.rotate(Math.PI / 4);
789:       ctx.fillStyle = q.type === 'main' ? '#f6e2ac' : '#7fb5c8';
790:       ctx.shadowColor = q.type === 'main' ? '#d8b16a' : '#7fb5c8';
791:       ctx.shadowBlur = 8;
792:       ctx.fillRect(-4, -4, 8, 8);
793:       ctx.restore();
794:     }
795: 
796:     // player
797:     const p = g.player;
798:     if (p) {
799:       const [mx, my] = toMap(p.position.x, p.position.z);
800:       ctx.save();
801:       ctx.translate(mx, my);
802:       ctx.rotate(-p.camYaw + Math.PI);
803:       ctx.fillStyle = '#ffffff';
804:       ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(5, 6); ctx.lineTo(0, 3); ctx.lineTo(-5, 6); ctx.closePath(); ctx.fill();
805:       ctx.restore();
806:       ctx.strokeStyle = 'rgba(255,255,255,.4)';
807:       ctx.beginPath(); ctx.arc(mx, my, 10, 0, Math.PI * 2); ctx.stroke();
808:     }
809: 
810:     // compass rose
811:     ctx.fillStyle = 'rgba(216,177,106,.55)';
812:     ctx.font = '700 11px Cinzel, serif';
813:     ctx.textAlign = 'center';
814:     ctx.fillText('N', w - 28, 24);
815:     ctx.strokeStyle = 'rgba(216,177,106,.35)';
816:     ctx.beginPath(); ctx.moveTo(w - 28, 30); ctx.lineTo(w - 28, 48); ctx.stroke();
817:   }
